-- ── THE PRE-IMAGE ──────────────────────────────────────────────────────────────────────────
create table public.sea_undo_0319 (
  kind text not null check (kind in ('raster', 'reach', 'stop', 'npc_course')),
  ref text not null,
  value jsonb,
  bytes bytea,
  primary key (kind, ref)
);
comment on table public.sea_undo_0319 is
  '0319: the sea as it stood before the harbours had their islands: the raster, every reach row, and each course this file mended. Read only by the forward rollback; drop it when the after-check has passed.';
alter table public.sea_undo_0319 enable row level security;
revoke all on table public.sea_undo_0319 from public, anon, authenticated;

insert into public.sea_undo_0319 (kind, ref, bytes) select 'raster', '1', cells from public.sea_raster where id = 1;
insert into public.sea_undo_0319 (kind, ref, value)
select 'reach', code, jsonb_build_object('snap_nm', snap_nm, 'lat', roadstead_lat, 'lon', roadstead_lon, 'reaches', reaches) from public.sea_reaches;

create temporary table sea_bits_0319 on commit drop as select cells || ''::bytea as old_cells, null::bytea as new_cells from public.sea_raster where id = 1;

-- ── THE STORED COURSES, READ BEFORE THE WATER MOVES ────────────────────────────────────────
-- was_refused: a course the land guard already refused today is not this file's to answer for.
create temporary table mend_0319 (key text primary key, old_course jsonb not null, was_refused boolean, new_course jsonb, new_nm numeric) on commit drop;
insert into mend_0319 (key, old_course)
select md5(c::text), c from (
  select course as c from public.standing_route_stops where course is not null and jsonb_typeof(course) = 'array' and jsonb_array_length(course) >= 2
  union select course from public.npc_courses
  union select args->'path' from public.orders
   where status = 'pending' and verb = 'SAIL' and jsonb_typeof(args->'path') = 'array' and jsonb_array_length(args->'path') >= 2) s
on conflict do nothing;
update mend_0319 set was_refused = voyage.path_refusal(old_course, (old_course->0->>0)::numeric, (old_course->0->>1)::numeric, (old_course->-1->>0)::numeric, (old_course->-1->>1)::numeric,
                                                  public.wc_num('course_join_nm'), 25, 25) is not null;

-- ── THE RASTER ─────────────────────────────────────────────────────────────────────────────
update public.sea_raster set cells = decode('', 'base64') where id = 1;
update sea_bits_0319 set new_cells = (select cells || ''::bytea from public.sea_raster where id = 1);

