-- ── THE MEND ───────────────────────────────────────────────────────────────────────────────
-- The row and column are path_refusal's own arithmetic, and bit 0 of a cell is its SEA bit.
create function pg_temp.cell_0319(p_lat float8, p_lon float8) returns int language sql immutable as $$
  select least(719, greatest(0, floor((90 - p_lat) / 0.25)::int)) * 1440 + ((floor((p_lon + 180) / 0.25)::int % 1440) + 1440) % 1440
$$;

-- Is the straight line between two points water, sampled at a quarter cell? For the mend's own legs.
create function pg_temp.open_0319(p_cells bytea, a float8[], b float8[]) returns boolean language plpgsql as $$
declare v_n int := greatest(2, ceil(voyage.gc_distance_nm(a[1], a[2], b[1], b[2]) / 3.75)::int); v_s int;
begin
  for v_s in 0 .. v_n loop
    if get_bit(p_cells, pg_temp.cell_0319(a[1] + (b[1] - a[1]) * v_s / v_n, voyage.lon_lerp(a[2], b[2], v_s::float8 / v_n)) * 2) = 0 then return false; end if;
  end loop;
  return true;
end $$;

-- The way round: a breadth-first walk over the open cells between two water points, then straightened
-- by line of sight. Returns the points strictly BETWEEN a and b, as a jsonb list; null if no way is found.
create function pg_temp.round_0319(p_cells bytea, a float8[], b float8[]) returns jsonb language plpgsql as $$
declare
  ca int := pg_temp.cell_0319(a[1], a[2]); cb int := pg_temp.cell_0319(b[1], b[2]);
  ra int := ca / 1440; rb int := cb / 1440; xa int := ca % 1440; xb int := cb % 1440;
  v_pad int; rmin int; rmax int; xmin int; xmax int; w int; h int;
  prev int[]; que int[]; v_head int; v_tail int; v_at int; v_r int; v_x int; v_nr int; v_nx int; v_n int; v_goal int; v_start int; d int;
  dr int[] := array[-1, 1, 0, 0, -1, -1, 1, 1]; dx int[] := array[0, 0, -1, 1, -1, 1, -1, 1];
  v_chain float8[] := '{}'; pts float8[][]; v_len int; v_i int; v_k int; v_out jsonb := '[]';
begin
  if xb - xa > 720 then xb := xb - 1440; elsif xa - xb > 720 then xb := xb + 1440; end if;
  foreach v_pad in array array[16, 48, 120] loop
    rmin := greatest(0, least(ra, rb) - v_pad); rmax := least(719, greatest(ra, rb) + v_pad);
    xmin := least(xa, xb) - v_pad; xmax := greatest(xa, xb) + v_pad;
    w := xmax - xmin + 1; h := rmax - rmin + 1;
    prev := array_fill(-1, array[w * h]); que := array_fill(0, array[w * h]);
    v_start := (ra - rmin) * w + (xa - xmin) + 1; v_goal := (rb - rmin) * w + (xb - xmin) + 1;
    prev[v_start] := 0; que[1] := v_start; v_head := 1; v_tail := 1;
    while v_head <= v_tail and prev[v_goal] = -1 loop
      v_at := que[v_head]; v_head := v_head + 1;
      v_r := (v_at - 1) / w + rmin; v_x := (v_at - 1) % w + xmin;
      for d in 1 .. 8 loop
        v_nr := v_r + dr[d]; v_nx := v_x + dx[d];
        continue when v_nr < rmin or v_nr > rmax or v_nx < xmin or v_nx > xmax;
        v_n := (v_nr - rmin) * w + (v_nx - xmin) + 1;
        continue when prev[v_n] <> -1;
        continue when v_n <> v_goal and get_bit(p_cells, (v_nr * 1440 + ((v_nx % 1440) + 1440) % 1440) * 2) = 0;
        prev[v_n] := v_at; v_tail := v_tail + 1; que[v_tail] := v_n;
      end loop;
    end loop;
    exit when prev[v_goal] <> -1;
  end loop;
  if prev[v_goal] = -1 then return null; end if;
  -- the chain, as cell centres, the start and goal cells among them: the line from a sample to the next cell may not cut a corner
  v_at := v_goal;
  v_chain := array[b[1], b[2]];
  while v_at <> 0 loop
    v_r := (v_at - 1) / w + rmin; v_x := (v_at - 1) % w + xmin;
    v_chain := array[90 - (v_r + 0.5) * 0.25, -180 + (((v_x % 1440) + 1440) % 1440 + 0.5) * 0.25] || v_chain;
    v_at := prev[v_at];
  end loop;
  v_chain := array[a[1], a[2]] || v_chain;
  v_len := array_length(v_chain, 1) / 2;
  v_i := 1;
  while v_i < v_len loop
    v_k := v_len;
    while v_k > v_i + 1 and not pg_temp.open_0319(p_cells, array[v_chain[2 * v_i - 1], v_chain[2 * v_i]], array[v_chain[2 * v_k - 1], v_chain[2 * v_k]]) loop
      v_k := v_k - 1;
    end loop;
    if v_k < v_len then v_out := v_out || jsonb_build_array(jsonb_build_array(round(v_chain[2 * v_k - 1]::numeric, 4), round(v_chain[2 * v_k]::numeric, 4))); end if;
    v_i := v_k;
  end loop;
  return v_out;
end $$;

-- One course mended. A stretch is SHUT when its cell is closed now and was open before (p_all: every closed
-- cell, at a finer step, for a course a first mend left refused: the server's samples fall where they fall). Returns the course, the same value when nothing was shut,
-- or null when a stretch has no way round or the course begins or ends in shut water.
create function pg_temp.mend_0319(p_course jsonb, p_new bytea, p_old bytea, p_all boolean) returns jsonb language plpgsql as $$
declare
  v_len int := jsonb_array_length(p_course); v_i int; v_s int; v_st int; v_nm float8;
  lat1 float8; lon1 float8; lat2 float8; lon2 float8; f float8;
  dlat float8[] := '{}'; dlon float8[] := '{}'; isv boolean[] := '{}'; shut boolean[] := '{}';
  v_n int; v_k int; v_e int; v_c int; v_any boolean := false; v_way jsonb; v_out jsonb := '[]';
begin
  for v_i in 0 .. v_len - 2 loop
    lat1 := (p_course->v_i->>0)::float8; lon1 := (p_course->v_i->>1)::float8;
    lat2 := (p_course->(v_i + 1)->>0)::float8; lon2 := (p_course->(v_i + 1)->>1)::float8;
    v_nm := voyage.gc_distance_nm(lat1, lon1, lat2, lon2);
    v_st := greatest(1, ceil(v_nm / case when p_all then 1.25 else 3.75 end)::int);
    for v_s in 0 .. v_st - 1 loop
      f := v_s::float8 / v_st;
      dlat := dlat || (lat1 + (lat2 - lat1) * f); dlon := dlon || voyage.lon_lerp(lon1, lon2, f); isv := isv || (v_s = 0);
    end loop;
  end loop;
  dlat := dlat || lat2; dlon := dlon || lon2; isv := isv || true;
  v_n := array_length(dlat, 1);
  for v_k in 1 .. v_n loop
    v_c := pg_temp.cell_0319(dlat[v_k], dlon[v_k]);
    shut := shut || (get_bit(p_new, v_c * 2) = 0 and (p_all or get_bit(p_old, v_c * 2) = 1));
    v_any := v_any or shut[v_k];
  end loop;
  if not v_any then return p_course; end if;
  if shut[1] or shut[v_n] then return null; end if;
  v_k := 1;
  while v_k <= v_n loop
    if shut[v_k + 1] is true then
      -- v_k is the last water sample before the stretch, v_e the first after it
      v_e := v_k + 1;
      while shut[v_e] loop v_e := v_e + 1; end loop;
      v_way := pg_temp.round_0319(p_new, array[dlat[v_k], dlon[v_k]], array[dlat[v_e], dlon[v_e]]);
      if v_way is null then return null; end if;
      v_out := v_out || jsonb_build_array(jsonb_build_array(round(dlat[v_k]::numeric, 4), round(dlon[v_k]::numeric, 4))) || v_way;
      v_k := v_e;
      isv[v_e] := true;
    else
      if isv[v_k] then
        v_out := v_out || jsonb_build_array(jsonb_build_array(round(dlat[v_k]::numeric, 4), round(dlon[v_k]::numeric, 4)));
      end if;
      v_k := v_k + 1;
    end if;
  end loop;
  return v_out;
end $$;

-- The last step over a mended course: drop every vertex a straight line over open water can skip, looking
-- 12 vertices ahead. A kept leg is not re-judged, so this can shorten a course and never break one.
create function pg_temp.tidy_0319(p_course jsonb, p_new bytea) returns jsonb language plpgsql as $$
declare v_n int := jsonb_array_length(p_course); v_i int := 0; v_k int; v_out jsonb := jsonb_build_array(p_course->0);
begin
  while v_i < v_n - 1 loop
    v_k := least(v_n - 1, v_i + 12);
    while v_k > v_i + 1 and not pg_temp.open_0319(p_new, array[(p_course->v_i->>0)::float8, (p_course->v_i->>1)::float8], array[(p_course->v_k->>0)::float8, (p_course->v_k->>1)::float8]) loop
      v_k := v_k - 1;
    end loop;
    v_out := v_out || jsonb_build_array(p_course->v_k);
    v_i := v_k;
  end loop;
  return v_out;
end $$;

-- A course's end, moved to the new roadstead if it stood at a moved harbour's old one.
create function pg_temp.ends_0319(p_course jsonb) returns jsonb language plpgsql as $$
declare v_c jsonb := p_course; v_i int; v_at int; m record; v_join float8 := public.wc_num('course_join_nm');
begin
  foreach v_i in array array[0, -1] loop
    select x.new_lat, x.new_lon into m from moved_0319 x
     where voyage.gc_distance_nm((v_c->v_i->>0)::float8, (v_c->v_i->>1)::float8, x.old_lat::float8, x.old_lon::float8) <= v_join
     order by voyage.gc_distance_nm((v_c->v_i->>0)::float8, (v_c->v_i->>1)::float8, x.old_lat::float8, x.old_lon::float8) limit 1;
    if found then
      v_at := case when v_i = 0 then 0 else jsonb_array_length(v_c) - 1 end;
      v_c := jsonb_set(v_c, array[v_at::text], jsonb_build_array(m.new_lat, m.new_lon));
    end if;
  end loop;
  return v_c;
end $$;

do $mend$
declare
  v_new bytea; v_old bytea; r record; v_c jsonb; v_join numeric := public.wc_num('course_join_nm');
  v_ref text; v_pass int; v_t2 jsonb; v_mended int := 0; v_refused int := 0; v_t timestamptz := clock_timestamp();
begin
  select new_cells, old_cells into v_new, v_old from sea_bits_0319;
  for r in select key, old_course, was_refused from mend_0319 loop
    v_c := pg_temp.mend_0319(pg_temp.ends_0319(r.old_course), v_new, v_old, false);
    if v_c is null then raise exception '0319: a stored course has no way round an island: %', left(r.old_course::text, 300); end if;
    v_ref := voyage.path_refusal(v_c, (v_c->0->>0)::numeric, (v_c->0->>1)::numeric, (v_c->-1->>0)::numeric, (v_c->-1->>1)::numeric, v_join, 25, 25);
    v_pass := 0;
    while v_ref like 'E_LAND%' and v_c is distinct from r.old_course and v_pass < 4 loop
      v_pass := v_pass + 1;
      v_c := coalesce(pg_temp.mend_0319(v_c, v_new, v_old, true), v_c);
      v_ref := voyage.path_refusal(v_c, (v_c->0->>0)::numeric, (v_c->0->>1)::numeric, (v_c->-1->>0)::numeric, (v_c->-1->>1)::numeric, v_join, 25, 25);
    end loop;
    if v_c is distinct from r.old_course then
      v_t2 := pg_temp.tidy_0319(v_c, v_new);
      if v_ref is null and voyage.path_refusal(v_t2, (v_t2->0->>0)::numeric, (v_t2->0->>1)::numeric, (v_t2->-1->>0)::numeric, (v_t2->-1->>1)::numeric, v_join, 25, 25) is null then v_c := v_t2; end if;
    end if;
    if v_ref is not null then v_refused := v_refused + 1; raise notice '0319: still refused after the mend: % %', v_ref, left(r.old_course::text, 120); end if;
    if v_c is distinct from r.old_course then
      v_mended := v_mended + 1;
      update mend_0319 set new_course = v_c,
        new_nm = (select sum((x->>'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(v_c)) x) where key = r.key;
    end if;
  end loop;
  raise notice '0319: % stored course(s) read, % mended, % refused for a reason of their own, in %', (select count(*) from mend_0319), v_mended, v_refused, clock_timestamp() - v_t;
end $mend$;

insert into public.sea_undo_0319 (kind, ref, value)
select 'stop', s.route_id::text || '|' || s.ord, jsonb_build_object('course', s.course, 'course_nm', s.course_nm)
  from public.standing_route_stops s join mend_0319 m on m.key = md5(s.course::text) where m.new_course is not null;
insert into public.sea_undo_0319 (kind, ref, value)
select 'npc_course', c.from_port::text || '|' || c.to_port::text, jsonb_build_object('course', c.course, 'nm', c.nm)
  from public.npc_courses c join mend_0319 m on m.key = md5(c.course::text) where m.new_course is not null;
update public.standing_route_stops s set course = m.new_course, course_nm = case when s.course_nm is null then null else m.new_nm end
  from mend_0319 m where m.key = md5(s.course::text) and m.new_course is not null;
update public.npc_courses c set course = m.new_course, nm = m.new_nm
  from mend_0319 m where m.key = md5(c.course::text) and m.new_course is not null;
update public.orders o set args = jsonb_set(o.args, '{path}', m.new_course)
  from mend_0319 m where o.status = 'pending' and o.verb = 'SAIL' and jsonb_typeof(o.args->'path') = 'array'
   and m.key = md5((o.args->'path')::text) and m.new_course is not null;

-- ── WHAT IS DERIVED FROM THE ROADSTEADS AND THE DISTANCES ──────────────────────────────────
update public.sea_leg_asks a set wave_min = d.wave_min, title_min = d.title_min, zones = d.zones
  from public.sea_leg_asks_derive() d
 where a.from_port = d.from_port and a.to_port = d.to_port
   and (a.wave_min, a.title_min, a.zones) is distinct from (d.wave_min, d.title_min, d.zones);

create temporary table haul_moved_0319 on commit drop as
select pg.port_id, pg.good_id, pg.haul_nm as old_nm, pg.haul as old_haul, h.haul_nm as new_nm, h.haul as new_haul
  from public.port_goods pg join world.haul_rows() h on h.port_id = pg.port_id and h.good_id = pg.good_id
 where (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul);
update public.port_goods pg set haul_nm = m.new_nm, haul = m.new_haul
  from haul_moved_0319 m where pg.port_id = m.port_id and pg.good_id = m.good_id;

-- ── SELF-ASSERT (the rows this file moved) ─────────────────────────────────────────────────
do $$
declare v_bad int; v_n int; v_h int; v_up numeric;
begin
  -- (a) the raster: the row holds this file's bytes, and the old bits are not the new
  if (select md5(cells) from public.sea_raster where id = 1) <> 'f9c09b78025f20c33bcff390d2d97dc4' then
    raise exception '0319 self-assert FAIL: the raster is not the one this file carries';
  end if;
  -- (b) every moved roadstead is what the ONE SQL rule answers, snap_nm long, and off the land
  select count(*) into v_bad from moved_0319 m join public.sea_reaches sr on sr.code = m.code join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) w
   where w.lat is distinct from sr.roadstead_lat or w.lon is distinct from sr.roadstead_lon or abs(w.nm - sr.snap_nm) > 0.01 or sr.snap_nm <= 0;
  if v_bad <> 0 then raise exception '0319 self-assert FAIL: % roadstead(s) are not what voyage.water_roadstead answers', v_bad; end if;
  -- (c) a closed island harbour: its own quay no longer stands on sailable water
  select count(*) into v_bad from moved_0319 m where voyage.water_snap_nm(m.old_lat, m.old_lon) = 0;
  if v_bad <> 0 then raise exception '0319 self-assert FAIL: % harbour(s) still stand on sailable water', v_bad; end if;
  -- (d) symmetric, for every pair of a moved harbour, and never under the great circle
  select count(*) into v_bad from public.sea_reaches a join moved_0319 m on m.code = a.code join public.sea_reaches b on b.code <> a.code
   where (a.reaches->>b.code) is distinct from (b.reaches->>a.code) or (a.reaches->>b.code) is null
      or (a.reaches->>b.code)::numeric < voyage.gc_distance_nm(a.roadstead_lat::float8, a.roadstead_lon::float8, b.roadstead_lat::float8, b.roadstead_lon::float8) - 0.2;
  if v_bad <> 0 then raise exception '0319 self-assert FAIL: % reach figure(s) of a moved harbour are one-way, missing or under the great circle', v_bad; end if;
  -- (e) every course this file mended sails, unless the land guard already refused it before this file
  select count(*) into v_bad from mend_0319 m where m.new_course is not null and not m.was_refused
     and voyage.path_refusal(m.new_course, (m.new_course->0->>0)::numeric, (m.new_course->0->>1)::numeric, (m.new_course->-1->>0)::numeric, (m.new_course->-1->>1)::numeric,
                             public.wc_num('course_join_nm'), 25, 25) is not null;
  if v_bad <> 0 then raise exception '0319 self-assert FAIL: % mended course(s) are refused by the land guard', v_bad; end if;
  -- (f) the pre-image holds the rows it promises, the raster among them
  select count(*) into v_n from mend_0319 where new_course is not null;
  if (select count(*) from public.sea_undo_0319 where kind = 'raster') <> 1 then raise exception '0319 self-assert FAIL: the raster has no pre-image'; end if;
  -- (g) the hauls this file moved equal the derivation
  select count(*) into v_h from haul_moved_0319;
  select count(*) into v_bad from haul_moved_0319 m join public.port_goods pg on pg.port_id = m.port_id and pg.good_id = m.good_id
   where (pg.haul_nm, pg.haul) is distinct from (m.new_nm, m.new_haul);
  if v_bad <> 0 then raise exception '0319 self-assert FAIL: % haul row(s) were not moved', v_bad; end if;
  select max(abs(new_nm - old_nm)) into v_up from haul_moved_0319;
  raise notice '0319 self-assert ok: THE HARBOURS HAVE THEIR ISLANDS. 182 cells closed, 28 roadsteads moved, 12359 pairs re-measured, % stored course(s) mended, % market row(s) took a new haul (widest % nm).', v_n, v_h, coalesce(v_up, 0);
end $$;
